application/json\":{\"schema\":{\"$ref\":\"#/components/schemas/StreamInitResponse\"}}}}}}},\"/query/stream/events/{streamId}\":{\"get\":{\"tags\":[\"Streaming\"],\"summary\":\"Ãcouter les Ã©vÃ©nements de streaming (SSE)\",\"description\":\"Ãcoute les Ã©vÃ©nements Server-Sent Events (SSE) pour un flux spÃ©cifique.\",\"operationId\":\"listenToStreamEvents\",\"parameters\":[{\"name\":\"streamId\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"string\"},\"description\":\"L''identifiant du flux de streaming.\"}],\"responses\":{\"200\":{\"description\":\"Le flux d''Ã©vÃ©nements SSE est ouvert.\",\"content\":{\"text/event-stream\":{\"schema\":{\"type\":\"string\",\"description\":\"ÃvÃ©nements de streaming du bot.\"}}}}}}},\"/conversation/{conversation_uuid}\":{\"post\":{\"tags\":[\"Conversations\"],\"summary\":\"RÃ©cupÃ©rer l''historique d''une conversation\",\"description\":\"RÃ©cupÃ¨re l''historique complet des messages pour une conversation donnÃ©e.\",\"operationId\":\"getConversationHistory\",\"parameters\":[{\"name\":\"conversation_uuid\",\"in\":\"path\",\"required\":true,\"schema\":{\"type\":\"string\",\"format\":\"uuid\"},\"description\":\"L''UUID de la conversation.\"}],\"responses\":{\"200\":{\"description\":\"Historique de la conversation retournÃ©.\",\"content\":{\"application/json\":{\"schema\":{\"type\":\"object\",\"properties\":{\"messages\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/components/schemas/Message\"}}}}}}}}}},\"/user/conversations\":{\"post\":{\"tags\":[\"Conversations\",\"Utilisateurs\"],\"summary\":\"RÃ©cupÃ©rer toutes les conversations d''un utilisateur\",\"description\":\"RÃ©cupÃ¨re une liste de toutes les conversations associÃ©es Ã  l''utilisateur authentifiÃ©.\",\"operationId\":\"getUserConversations\",\"responses\":{\"200\":{\"description\":\"Liste des conversations de l''utilisateur.\",\"content\":{\"application/json\":{\"schema\":{\"type\":\"array\",\"items\":{\"$ref\":\"#/components/schemas/ConversationSummary\"}}}}}}}},\